  "Choose a chat to follow up": "\u30D5\u30A9\u30ED\u30FC\u30A2\u30C3\u30D7\u3059\u308B\u30C1\u30E3\u30C3\u30C8\u3092\u9078\u629E",
  "Choose a connector": "\u30B3\u30CD\u30AF\u30BF\u3092\u9078\u629E",
  "Choose a document": "\u8CC7\u6599\u3092\u9078\u629E",
