  "Hardware acceleration": "\u30CF\u30FC\u30C9\u30A6\u30A7\u30A2\u30A2\u30AF\u30BB\u30E9\u30EC\u30FC\u30B7\u30E7\u30F3",
  "Has changes": "\u5909\u66F4\u3042\u308A",
